808	/// Creates a [Matcher] from a [StringSet]
809	///
810	/// ## Errors
811	///
812	/// It can raise an error if the patterns aren't valid
813	pub fn to_matcher(
814	    working_directory: Option<PathBuf>,
815	    string_set: Option<&StringSet>,
816	) -> Result<Matcher, WorkspaceError> {
817	    let mut matcher = Matcher::empty();
818	    if let Some(working_directory) = working_directory {
819	        matcher.set_root(working_directory)
820	    }
821	    if let Some(string_set) = string_set {
822	        for pattern in string_set.iter() {
823	            matcher.add_pattern(pattern).map_err(|err| {
824	                WorkspaceError::Configuration(ConfigurationDiagnostic::new_invalid_ignore_pattern(
825	                    pattern.to_string(),
826	                    err.msg.to_string(),
827	                ))
828	            })?;
829	        }
830	    }
831	    Ok(matcher)
832	}
