834	fn to_git_ignore(path: PathBuf, matches: &[String]) -> Result<Gitignore, WorkspaceError> {
835	    let mut gitignore_builder = GitignoreBuilder::new(path.clone());
836	
837	    for the_match in matches {
838	        gitignore_builder
839	            .add_line(Some(path.clone()), the_match)
840	            .map_err(|err| {
841	                WorkspaceError::Configuration(ConfigurationDiagnostic::InvalidIgnorePattern(
842	                    InvalidIgnorePattern {
843	                        message: err.to_string(),
844	                    },
845	                ))
846	            })?;
847	    }
848	    let gitignore = gitignore_builder.build().map_err(|err| {
849	        WorkspaceError::Configuration(ConfigurationDiagnostic::InvalidIgnorePattern(
850	            InvalidIgnorePattern {
851	                message: err.to_string(),
852	            },
853	        ))
854	    })?;
855	    Ok(gitignore)
856	}
