93	    fn resolve_format_options(
94	        global: &FormatSettings,
95	        overrides: &OverrideSettings,
96	        language: &JsFormatterSettings,
97	        path: &RomePath,
98	    ) -> JsFormatOptions {
99	        let indent_style = if let Some(indent_style) = language.indent_style {
100	            indent_style
101	        } else {
102	            global.indent_style.unwrap_or_default()
103	        };
