105	            line_width
106	        } else {
107	            global.line_width.unwrap_or_default()
108	        };
109	        let indent_width = if let Some(indent_width) = language.indent_width {
110	            indent_width
111	        } else {
112	            global.indent_width.unwrap_or_default()
113	        };
114	
115	        let line_ending = if let Some(line_ending) = language.line_ending {
116	            line_ending
117	        } else {
118	            global.line_ending.unwrap_or_default()
119	        };
120	        let options = JsFormatOptions::new(path.as_path().try_into().unwrap_or_default())
121	            .with_indent_style(indent_style)
122	            .with_indent_width(indent_width)
123	            .with_line_width(line_width)
124	            .with_line_ending(line_ending)
125	            .with_quote_style(language.quote_style.unwrap_or_default())
126	            .with_jsx_quote_style(language.jsx_quote_style.unwrap_or_default())
127	            .with_quote_properties(language.quote_properties.unwrap_or_default())
128	            .with_trailing_comma(language.trailing_comma.unwrap_or_default())
129	            .with_semicolons(language.semicolons.unwrap_or_default())
130	            .with_arrow_parentheses(language.arrow_parentheses.unwrap_or_default())
131	            .with_bracket_spacing(language.bracket_spacing.unwrap_or_default())
132	            .with_bracket_same_line(language.bracket_same_line.unwrap_or_default());
133	
134	        overrides.override_js_format_options(path, options)
135	    }
