3	use crate::execute::diagnostics::{ContentDiffAdvice, FormatDiffDiagnostic};
4	use crate::execute::Execution;
5	use crate::{CliDiagnostic, CliSession};
6	use biome_console::{markup, ConsoleExt};
7	use biome_diagnostics::Diagnostic;
8	use biome_diagnostics::PrintDiagnostic;
9	use biome_fs::RomePath;
10	use biome_service::workspace::{
11	    ChangeFileParams, FeatureName, FeaturesBuilder, FixFileParams, FormatFileParams, Language,
12	    OpenFileParams, OrganizeImportsParams, PullDiagnosticsParams, RuleCategories,
13	    SupportsFeatureParams,
14	};
15	use biome_service::WorkspaceError;
