18	pub(crate) fn run<'a>(
19	    session: CliSession,
20	    mode: &'a Execution,
21	    rome_path: RomePath,
22	    content: &'a str,
23	    verbose: bool,
24	) -> Result<(), CliDiagnostic> {
25	    let workspace = &*session.app.workspace;
26	    let console = &mut *session.app.console;
27	    let mut version = 0;
28	
29	    if mode.is_format() {
30	        let file_features = workspace.file_features(SupportsFeatureParams {
31	            path: rome_path.clone(),
32	            feature: FeaturesBuilder::new().with_formatter().build(),
33	        })?;
34	        if file_features.is_protected() {
35	            let protected_diagnostic =
36	                WorkspaceError::protected_file(rome_path.display().to_string());
37	            if protected_diagnostic.tags().is_verbose() {
38	                if verbose {
39	                    console.error(markup! {{PrintDiagnostic::verbose(&protected_diagnostic)}})
40	                }
41	            } else {
42	                console.error(markup! {{PrintDiagnostic::simple(&protected_diagnostic)}})
43	            }
44	            console.append(markup! {{content}});
45	            return Ok(());
46	        };
47	        if file_features.supports_for(&FeatureName::Format) {
48	            workspace.open_file(OpenFileParams {
49	                path: rome_path.clone(),
50	                version: 0,
51	                content: content.into(),
52	                language_hint: Language::default(),
53	            })?;
54	            let printed = workspace.format_file(FormatFileParams { path: rome_path })?;
55	
56	            console.append(markup! {
57	                {printed.as_code()}
58	            });
59	        } else {
60	            console.append(markup! {
61	                {content}
62	            });
63	            console.error(markup!{
64	                    <Warn>"The content was not formatted because the formatter is currently disabled."</Warn>
65	                })
66	        }
67	    } else if mode.is_check() || mode.is_lint() {
68	        let mut diagnostics = Vec::new();
69	        let mut new_content = Cow::Borrowed(content);
70	
71	        workspace.open_file(OpenFileParams {
72	            path: rome_path.clone(),
73	            version: 0,
74	            content: content.into(),
75	            language_hint: Language::default(),
76	        })?;
77	        // apply fix file of the linter
78	        let file_features = workspace.file_features(SupportsFeatureParams {
79	            path: rome_path.clone(),
80	            feature: FeaturesBuilder::new()
81	                .with_linter()
82	                .with_organize_imports()
83	                .with_formatter()
84	                .build(),
85	        })?;
86	
87	        if file_features.is_protected() {
88	            let protected_diagnostic =
89	                WorkspaceError::protected_file(rome_path.display().to_string());
90	            if protected_diagnostic.tags().is_verbose() {
91	                if verbose {
92	                    console.error(markup! {{PrintDiagnostic::verbose(&protected_diagnostic)}})
93	                }
94	            } else {
95	                console.error(markup! {{PrintDiagnostic::simple(&protected_diagnostic)}})
96	            }
97	            console.append(markup! {{content}});
98	            return Ok(());
99	        };
100	
101	        if let Some(fix_file_mode) = mode.as_fix_file_mode() {
102	            if file_features.supports_for(&FeatureName::Lint) {
103	                let fix_file_result = workspace.fix_file(FixFileParams {
104	                    fix_file_mode: *fix_file_mode,
105	                    path: rome_path.clone(),
106	                    should_format: mode.is_check()
107	                        && file_features.supports_for(&FeatureName::Format),
108	                })?;
109	                if fix_file_result.code != new_content {
110	                    version += 1;
111	                    workspace.change_file(ChangeFileParams {
112	                        content: fix_file_result.code.clone(),
113	                        path: rome_path.clone(),
114	                        version,
115	                    })?;
116	                    new_content = Cow::Owned(fix_file_result.code);
117	                }
118	            }
119	
120	            if file_features.supports_for(&FeatureName::OrganizeImports) && mode.is_check() {
121	                let result = workspace.organize_imports(OrganizeImportsParams {
122	                    path: rome_path.clone(),
123	                })?;
124	                if result.code != new_content {
125	                    version += 1;
126	                    workspace.change_file(ChangeFileParams {
127	                        content: result.code.clone(),
128	                        path: rome_path.clone(),
129	                        version,
130	                    })?;
131	                    new_content = Cow::Owned(result.code);
132	                }
133	            }
134	        }
135	
136	        if !mode.is_check_apply_unsafe() {
137	            let result = workspace.pull_diagnostics(PullDiagnosticsParams {
138	                categories: RuleCategories::LINT | RuleCategories::SYNTAX,
139	                path: rome_path.clone(),
140	                max_diagnostics: mode.max_diagnostics.into(),
141	            })?;
142	            diagnostics.extend(result.diagnostics);
143	        }
144	
145	        if file_features.supports_for(&FeatureName::Format) && mode.is_check() {
146	            let printed = workspace.format_file(FormatFileParams {
147	                path: rome_path.clone(),
148	            })?;
149	            if mode.is_check_apply() || mode.is_check_apply_unsafe() {
150	                if printed.as_code() != new_content {
151	                    new_content = Cow::Owned(printed.into_code());
152	                }
153	            } else {
154	                let diagnostic = FormatDiffDiagnostic {
155	                    file_name: rome_path.display().to_string(),
156	                    diff: ContentDiffAdvice {
157	                        new: printed.as_code().to_string(),
158	                        old: content.to_string(),
159	                    },
160	                };
161	                diagnostics.push(biome_diagnostics::serde::Diagnostic::new(diagnostic));
162	            }
163	        }
164	
165	        match new_content {
166	            Cow::Borrowed(original_content) => {
167	                console.append(markup! {
168	                    {original_content}
169	                });
170	            }
171	            Cow::Owned(new_content) => {
172	                console.append(markup! {
173	                    {new_content}
174	                });
175	            }
176	        }
177	        if !diagnostics.is_empty() {
178	            for diag in diagnostics {
179	                console.error(markup! {
180	                    {if verbose { PrintDiagnostic::verbose(&diag) } else { PrintDiagnostic::simple(&diag) }}
181	                })
182	            }
183	        }
184	    } else {
185	        console.append(markup! {{content}});
186	    }
187	    Ok(())
188	}
