                    new_content = Cow::Owned(fix_file_result.code);
                }
            }

            if file_features.supports_for(&FeatureName::OrganizeImports) && mode.is_check() {
                let result = workspace.organize_imports(OrganizeImportsParams {
                    path: rome_path.clone(),
